import * as T from './three.module.js';
const cube=new T.BoxGeometry(1,1,1),mats=new Map();
function mat(c,glow=0){const k=c+'-'+glow;if(!mats.has(k))mats.set(k,new T.MeshStandardMaterial({color:c,roughness:.87,metalness:0,emissive:glow?c:0,emissiveIntensity:glow}));return mats.get(k)}
function block(g,x,y,z,w,h,d,c,glow=0){const b=new T.Mesh(cube,mat(c,glow));b.position.set(x,y,z);b.scale.set(w,h,d);b.castShadow=h>.08;b.receiveShadow=true;g.add(b);return b}
function texture(kind){const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d');let seed=123;const rng=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
 if(kind==='stone'){ctx.fillStyle='#626b69';ctx.fillRect(0,0,64,64);for(let row=0;row<4;row++)for(let col=-1;col<3;col++){const x=col*32+(row%2)*16,y=row*16;const c=144+Math.floor(rng()*22);ctx.fillStyle=`rgb(${c},${c+7},${c-2})`;ctx.fillRect(x+1,y+1,30,14);ctx.fillStyle='#bec2a9';ctx.fillRect(x+2,y+1,28,1);ctx.fillStyle='#7a826f';ctx.fillRect(x+1,y+14,30,1);for(let k=0;k<13;k++){const px=x+3+Math.floor(rng()*24),py=y+3+Math.floor(rng()*9);ctx.fillStyle=k%2?'#adb29b':'#8b957f';ctx.fillRect(px,py,Math.floor(rng()*3)+1,1)}}}
 else if(kind==='sand'){ctx.fillStyle='#bda989';ctx.fillRect(0,0,64,64);for(let i=0;i<170;i++){ctx.fillStyle=i%3?'#cdbc9c':'#a9997d';ctx.fillRect(Math.floor(rng()*32)*2,Math.floor(rng()*32)*2,2,2)}for(let j=0;j<4;j++){ctx.fillStyle='#928870';ctx.fillRect(0,j*16,64,1);ctx.fillRect(j%2?16:0,j*16,1,16);ctx.fillRect(j%2?48:32,j*16,1,16)}}
 else if(kind==='wood'){ctx.fillStyle='#87633f';ctx.fillRect(0,0,64,64);for(let x=0;x<64;x+=16){ctx.fillStyle='#4a392c';ctx.fillRect(x,0,2,64);ctx.fillStyle='#b38d58';ctx.fillRect(x+2,0,1,64)}for(let k=0;k<90;k++){ctx.fillStyle=k%2?'#9b794c':'#725236';ctx.fillRect(Math.floor(rng()*60),Math.floor(rng()*60),2,Math.floor(rng()*15)+2)}}
 else{ctx.fillStyle='#568345';ctx.fillRect(0,0,64,64);for(let i=0;i<300;i++){ctx.fillStyle=['#719850','#476f3c','#689449','#85a65a'][i%4];ctx.fillRect(Math.floor(rng()*32)*2,Math.floor(rng()*32)*2,2,2)}}const t=new T.CanvasTexture(canvas);t.colorSpace=T.SRGBColorSpace;t.magFilter=t.minFilter=T.NearestFilter;t.wrapS=t.wrapT=T.RepeatWrapping;return t;}
export function detailedWorld(scene,SOLIDS,wallMeshes,ground,grassMaterial){
 const stoneMap=texture('stone'),sandMap=texture('sand'),woodMap=texture('wood'),grassMap=texture('grass');const stone=new T.MeshStandardMaterial({map:stoneMap,roughness:.95}),sand=new T.MeshStandardMaterial({map:sandMap,roughness:1}),wood=new T.MeshStandardMaterial({map:woodMap,roughness:.9});grassMaterial.map=grassMap;ground.material.map=sandMap.clone();ground.material.map.repeat.set(28,24);ground.material.map.needsUpdate=true;
 const g=new T.Group();scene.add(g);
 function tiled(mesh,w,h,d,material){const geo=cube.clone(),uv=geo.attributes.uv;for(let i=0;i<24;i++){const f=Math.floor(i/4);uv.setXY(i,uv.getX(i)*(f<2?d:f<4?w:w)/1.8,uv.getY(i)*(f<2?h:f<4?d:h)/1.8)}uv.needsUpdate=true;mesh.geometry=geo;mesh.material=material;}
 function facing(x,z,rotation,fn){const local=new T.Group();local.position.set(x,0,z);local.rotation.y=rotation;g.add(local);fn(local);}
 function doorway(local,y=0){block(local,0,1.23+y,.06,1.5,2.46,.15,0x374342);for(const x of[-.90,.90]){block(local,x,1.3+y,.15,.28,2.6,.31,0xd3c5a1);for(let k=0;k<5;k++)block(local,x,.25+y+k*.5,.318,.32,.038,.038,0x857e65)}for(let k=0;k<3;k++)block(local,0,2.58+y+k*.14,.14,2.07-k*.2,.14,.4,0xc6bc9b);for(let x=-.62;x<=.65;x+=.21)block(local,x,1.20+y,.16,.17,2.30,.1,0x69523b);block(local,0,.58+y,.225,1.37,.10,.09,0x303e3f);block(local,0,1.80+y,.225,1.37,.10,.09,0x303e3f);for(const x of[-.34,.34])block(local,x,1.21+y,.25,.07,.16,.10,0xc9ac65);}
 function window(local,y,w=1.3){block(local,0,y,.025,w+.26,1.31,.13,0x475d5b);block(local,0,y,.10,w,1.05,.08,0x365762);block(local,0,y+.18,.15,w-.08,.025,.02,0x8ccac5);for(const x of[-w/2-.045,w/2+.045])block(local,x,y,.15,.09,1.32,.17,0xb1aa89);for(const yy of[y-.64,y+.64])block(local,0,yy,.16,w+.25,.09,.19,0xcfc2a0);block(local,0,y,.18,.07,1.16,.06,0x182f34);block(local,0,y,.18,w,.07,.06,0x182f34);block(local,0,y-.71,.15,w+.49,.17,.55,0x8e9b86);}
 for(let i=0;i<SOLIDS.length;i++){const[x,z,w,d,h]=SOLIDS[i],mesh=wallMeshes[i],isCrate=i>=10&&w<=5&&d<=4;const material=isCrate?wood:i%3===0?sand:stone;tiled(mesh,w,h,d,material);
  if(i<4){for(let t=-((w>d?w:d)/2)+2;t<(w>d?w:d)/2;t+=5){const xx=w>d?x+t:x,zz=w>d?z:z+t;block(g,xx,h/2,zz,w>d?.47:1.2,h+.25,w>d?1.2:.47,0x62796f);block(g,xx,h+.1,zz,w>d?.7:1.45,.25,w>d?1.45:.7,0xb1b89b)}continue}
  if(isCrate){for(const side of[-1,1]){const zf=z+side*(d/2+.065);for(const xx of[x-w/2+.15,x+w/2-.15])block(g,xx,h/2,zf,.23,h+.03,.15,0x453e35);for(const yy of[.21,h-.21])block(g,x,yy,zf,w+.08,.17,.13,0x535c58);for(let k=0;k<4;k++)block(g,x-w/2+.35+k*.32,h*.66,zf+side*.075,.17,.25,.025,k%2?0xcdbb65:0x292f2d).rotation.z=-.3;for(const xx of[x-w/2+.16,x+w/2-.16])for(const yy of[.22,h-.22])block(g,xx,yy,zf+side*.08,.075,.075,.04,0xb9b39d);}block(g,x,h+.09,z,w*.72,.14,d*.72,0x967951);continue}
  // Repeated stone corner blocks give every building a readable, block-scale silhouette.
  for(const dx of[-w/2,w/2])for(const dz of[-d/2,d/2])for(let y=.33;y<h;y+=.66){block(g,x+dx,y,z+dz,.29,.57,.29,y%1.2>.5?0xb8baa0:0xced0b3)}
  for(const side of[-1,1]){const zz=z+side*(d/2+.06);if(w>=6){facing(x,zz,side===1?0:Math.PI,l=>doorway(l));for(const xx of[-w*.31,w*.31])facing(x+xx,zz,side===1?0:Math.PI,l=>window(l,h*.64,.95));}
   else facing(x,zz,side===1?0:Math.PI,l=>window(l,Math.min(h*.6,2.1),1.25));
   block(g,x,h-.35,zz,w+.17,.10,.16,0x687e6d);block(g,x,.18,zz,w+.16,.27,.16,0x637266);
  }
  for(const side of[-1,1])for(let off=-d/2+1.3;off<d/2;off+=2.6)facing(x+side*(w/2+.07),z+off,side===1?Math.PI/2:-Math.PI/2,l=>window(l,Math.min(h*.6,2.4),1.05));
  // Roof parapets, copper trim and small flowering moss clusters.
  for(const dx of[-w*.35,w*.35])for(const dz of[-d*.35,d*.35]){block(g,x+dx,h+.58,z+dz,.43,.35,.43,0x698452);block(g,x+dx+.12,h+.78,z+dz,.22,.13,.2,0x93af67)}
  for(const side of[-1,1]){const xx=x+side*w*.43;block(g,xx,h*.63,z+d/2+.18,.09,h*.45,.05,0x4a754c);for(let k=0;k<4;k++)block(g,xx+Math.sin(k)*.14,h*.42+k*.25,z+d/2+.22,.25,.15,.07,k%2?0x648b4d:0x87a458)}
 }
 // Inset stepping stones and patterned pavers; no collision on floor details.
 let count=0;for(let x=-26;x<=26;x+=2)for(let z=-22;z<=22;z+=2){if(SOLIDS.some(([cx,cz,w,d])=>Math.abs(x-cx)<w/2+1&&Math.abs(z-cz)<d/2+1))continue;if((Math.abs(x)<7||Math.abs(z-10)<3||Math.abs(z+11)<3)&&count++%2===0){block(g,x,.027,z,1.73,.045,1.73,0xa5a895);block(g,x-.74,.052,z,.025,.012,1.5,0xc6c5a6);block(g,x,.052,z-.74,1.5,.012,.025,0xc6c5a6)}else if(count%5===0){block(g,x,.026,z,.75,.044,.72,0x9b9f8a)}}
 // Distinct site signage and banners attached to buildings, visible from the approaches.
 for(const side of[-1,1]){const local=new T.Group();local.position.set(side*17,0,-.88);g.add(local);const color=side===-1?0x399789:0xb65e45;block(local,0,2.75,0,1.24,1.77,.12,color);block(local,0,3.68,0,1.45,.12,.22,0x394e4d);block(local,0,1.9,.04,1.05,.14,.09,0xe2c78c);block(local,0,2.8,.09,.10,.93,.02,0xe8d4a7);if(side===-1){block(local,-.2,2.89,.09,.10,.70,.02,0xe8d4a7).rotation.z=-.30;block(local,.2,2.89,.09,.10,.70,.02,0xe8d4a7).rotation.z=.30;block(local,0,2.76,.09,.4,.09,.02,0xe8d4a7)}else{for(const y of[2.56,2.98])block(local,.14,y,.09,.4,.10,.02,0xe8d4a7);block(local,.34,2.77,.09,.1,.51,.02,0xe8d4a7)}}
 // Tufts and flowers grow along cover, leaving movement lanes clear.
 for(let i=4;i<SOLIDS.length;i++){const[x,z,w,d,h]=SOLIDS[i];if(h<2)continue;for(let k=0;k<3;k++){const xx=x-w/2+.4+k*.47,zz=z+d/2+.22;block(g,xx,.14,zz,.06,.28,.045,0x4b713e);block(g,xx-.10,.16,zz,.16,.045,.07,0x6c8c46);block(g,xx+.08,.2,zz,.12,.044,.07,0x6d944d);if(k===1){block(g,xx,.31,zz,.15,.09,.15,0xd0af66);block(g,xx,.36,zz,.06,.035,.06,0xf0d28c)}}}
 return{group:g,stoneMap,sandMap,woodMap};
}
